root=Path(sys.argv[sys.argv.index('--')+1]);o=bpy.data.objects['Buzz_Skinned'];e=np.load(root/'buffers/expected.npz');order=np.argsort(e['source_triangles']);meta=json.loads((root/'check/final-metadata.json').read_text());m=next(m for m in meta if m['path'].endswith('/SK_Male_Teen_01.uasset'));d=next(d for d in (root/'check').glob('final-mesh-readback-*') if d.is_dir() and json.loads((d/'mesh.json').read_text())['source_sha256']==m['sha256']);idx=np.fromfile(d/'indices.u32',dtype='<u4').reshape(-1,3)[order];p=np.fromfile(d/'positions.f32',dtype='<f4').reshape(-1,3)*[.01,-.01,.01];n=np.fromfile(d/'normals.f32',dtype='<f4').reshape(-1,3)*[1,-1,1];n/=np.linalg.norm(n,axis=1,keepdims=True);o.data.calc_loop_triangles();tri=np.array([t.vertices[:] for t in o.data.loop_triangles]);source=np.array([v.co[:] for v in o.data.vertices]);error=float(np.max(abs(source[tri]-p[idx])));assert error<2e-6;assert len(o.find_armature().data.bones)==230;assert len(o.data.loops)==len(idx)*3;o.data.normals_split_custom_set(n[idx].reshape(-1,3).tolist());bpy.context.preferences.filepaths.save_version=0;bpy.ops.wm.save_as_mainfile(filepath=str(root/'Buzz-Arms-Cooked-Verified.blend'),compress=True);(root/'blender-cooked-validation.json').write_text(json.dumps({'fresh_reopen':True,'native_reference_bones':230,'source_to_packaged_position_error_m':error,'triangle_corners_compared':int(idx.size),'preview_normals':'Actual fresh CUE4Parse read-back, restored to Blender','source_geometry_weights_UVs_unchanged':True,'runtime':'NOT TESTED'},indent=2));print('COOKED_SOURCE_MATCH',error)
